// Visitor assistant: live AI when configured; clearly labelled published-information guide otherwise.
(()=>{
const panel=document.querySelector("#assistant-panel"),launcher=document.querySelector("#assistant-launcher"),messages=document.querySelector("#assistant-messages"),input=document.querySelector("#assistant-input"),form=document.querySelector("#assistant-form"),mode=document.querySelector("#assistant-mode"),notice=document.querySelector("#assistant-notice");
let aiAvailable=false,busy=false,history=[],generation=0;
function bubble(text,role){const node=document.createElement("p");node.className="chat-bubble "+role;node.textContent=text;messages.append(node);messages.scrollTop=messages.scrollHeight;return node}
function welcome(){bubble("Hello! I can answer questions about each training program and service, paid internships, fees, quizzes, projects, career preparation and forms. What would you like to know?","assistant")}
function open(){panel.hidden=false;launcher.setAttribute("aria-expanded","true");input.focus()}
function close(){panel.hidden=true;launcher.setAttribute("aria-expanded","false");launcher.focus()}
launcher.addEventListener("click",()=>panel.hidden?open():close());document.querySelector("#assistant-close").addEventListener("click",close);
document.querySelector("#assistant-enquiry").addEventListener("click",()=>{const summary=history.filter(m=>m.role==="user").slice(-3).map(m=>m.content).join("; ");if(summary){const field=document.querySelector('[name="message"]');if(field){if(!field.value)field.value="I would like guidance on: "+summary}else document.querySelector("#assistant-enquiry").href="contact.html?type=General&interest=General%20enquiry&message="+encodeURIComponent("I would like guidance on: "+summary)+"#enquiry"}close()});
document.querySelector("#assistant-reset").addEventListener("click",()=>{generation++;history=[];messages.replaceChildren();welcome()});
panel.addEventListener("keydown",e=>{if(e.key==="Escape"){close();return}if(e.key==="Tab"){const nodes=[...panel.querySelectorAll("button,input,a")].filter(n=>!n.disabled);if(e.shiftKey&&document.activeElement===nodes[0]){e.preventDefault();nodes.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===nodes.at(-1)){e.preventDefault();nodes[0].focus()}}});
const knowledgeEntries=[{"topic":"internship fees","aliases":["internship fee","internship price","internship cost","paid internship"],"answer":"Internship fees payable by applicants: 1 month ₹499, 2 months ₹999, 3 months ₹1,299, 6 months ₹1,999. These are fees, not salary or stipend. Choose a duration in the paid internship application form and submit payment proof for team verification.","kind":"faq"},{"topic":"internship monthly support","aliases":["monthly assessment","monthly task","internship benefit","internship support"],"answer":"Internships include monthly tasks, monthly assessments, learning notes and project support. An internship certificate and experience letter are provided after agreed completion requirements are met.","kind":"faq"},{"topic":"internship application","aliases":["apply internship","apply for internship","internship application"],"answer":"Open Programs → Internships → Apply for Paid Internship. Select your domain and duration, complete learner and payment details, and upload a receipt. Submission does not confirm acceptance or payment.","kind":"faq"},{"topic":"internship duration","aliases":["internship duration","internship month","how long internship"],"answer":"Choose 1, 2, 3 or 6 months. Applicant fees are ₹499, ₹999, ₹1,299 and ₹1,999 respectively. Confirm availability and terms with the team.","kind":"faq"},{"topic":"upi payment","aliases":["upi","scanner","qr code","scan to pay"],"answer":"UPI ID: 7060711685@kotakbank. The supplied QR shows recipient MD AAJAM. Enter the fee for the selected duration, or ₹999 for Communication Skills registration. Check recipient and amount in your payment app. This chat cannot verify a transaction.","kind":"faq"},{"topic":"payment verification","aliases":["payment verified","verify payment","payment status","paid already","payment confirmation"],"answer":"Payments require manual team verification. Submit the transaction reference and receipt in the relevant application form. The chatbot cannot confirm payment, enrolment or acceptance.","kind":"faq"},{"topic":"payment receipt","aliases":["payment proof","payment receipt","utr","transaction reference"],"answer":"Communication and internship forms require your transaction reference, payer name, payment date and a PNG, JPG or PDF receipt up to 5 MB. The team checks these details.","kind":"faq"},{"topic":"communication registration","aliases":["communication registration","communication fee","communication price"],"answer":"Communication Skills lasts 3 months and costs ₹7,999 total: ₹7,000 training + ₹999 registration. Its separate registration form includes UPI details and receipt upload. Payment needs team verification.","kind":"faq"},{"topic":"placement support","aliases":["placement","employment guarantee","guarantee employment"],"answer":"Yes, we provide placement support, including preparation and guidance. However, we do not guarantee employment.","kind":"faq"},{"topic":"training certificates","aliases":["training certificate","certificate requirement"],"answer":"Training certificates document completed training. Confirm attendance, assignment and completion requirements with the team before enrolment.","kind":"faq"},{"topic":"internship certificates","aliases":["internship certificate"],"answer":"Internship certificates are issued after the agreed completion criteria are met, including relevant tasks, assessments and project work. Confirm the exact criteria with the team.","kind":"faq"},{"topic":"experience letter","aliases":["experience letter"],"answer":"An experience letter documents completed internship experience and is provided subject to agreed completion requirements. Ask the team about issuing details.","kind":"faq"},{"topic":"demo certificate","aliases":["demo certificate","certificate demo","watermark"],"answer":"The displayed certificate has a DEMO watermark and placeholder information. It is a sample design, not an issued credential.","kind":"faq"},{"topic":"live training","aliases":["live training","live session","live class"],"answer":"Training includes instructor-led live sessions and practical guidance. Ask the team for the confirmed batch schedule and delivery arrangements.","kind":"faq"},{"topic":"recorded sessions","aliases":["recorded","recording"],"answer":"Recorded sessions help you revisit training concepts. Confirm access arrangements and availability with the team.","kind":"faq"},{"topic":"doubt sessions","aliases":["doubt","question support"],"answer":"Doubt sessions help you work through concepts and practical tasks that need clarification. Ask the team for timings and format.","kind":"faq"},{"topic":"batch timing","aliases":["batch","timing","schedule","start date"],"answer":"Batch dates, timings and availability need confirmation from Qelviora. Share your program and preferred timing through the enquiry form.","kind":"faq"},{"topic":"course fees","aliases":["course fee","training fee","program fee"],"answer":"Communication Skills costs ₹7,999 total, split into ₹7,000 training and ₹999 registration. Fees for other training programs must be confirmed with the team. Internship fees are listed separately.","kind":"faq"},{"topic":"refund policy","aliases":["refund","cancellation"],"answer":"Refund and cancellation terms are not published here. Confirm them with Qelviora before paying or enrolling.","kind":"faq"},{"topic":"quiz library","aliases":["quiz","assessment practice","skill test"],"answer":"Learning Experience → Quiz has 51 skills, each with 20 quizzes of 3 questions. Every question has 3 choices and immediate answer feedback. Foundation questions may reappear across quizzes for revision. Scores are not saved.","kind":"faq"},{"topic":"learning notes","aliases":["learning notes","study notes"],"answer":"Internship benefits include notes to support practice and revision. Skill lessons also offer practice tasks and optional notes; page notes are not saved.","kind":"faq"},{"topic":"career finder","aliases":["find my path","find your path","career path","career roadmap"],"answer":"Find Your Path asks five questions about background, interests, goals, experience and weekly practice time. It suggests a practical route and relevant resources without login.","kind":"faq"},{"topic":"career center","aliases":["career center","career centre"],"answer":"Programs → Career Center provides résumé, LinkedIn, interview, SQL, Python, Power BI, aptitude, communication, mock interview, roadmap and portfolio resources.","kind":"faq"},{"topic":"projects hub","aliases":["project hub","project briefs","all projects"],"answer":"Programs → Projects has five practice briefs: Retail Sales Intelligence Dashboard, Customer Segmentation Analysis, Loan Eligibility Prediction, E-Commerce Analytics and AI Resume Screening.","kind":"faq"},{"topic":"practice form","aliases":["start practice","practice form","submit project"],"answer":"Start Practice opens a separate form with the project selected. Share learner details, learning goals, a practice plan, optional project link and optional attachment. It is sent to the team for review.","kind":"faq"},{"topic":"business development opening","aliases":["business development executive"],"answer":"Business Development Executive: fresher opening, advertised salary ₹3.5 LPA. Apply through Careers using the separate candidate form and résumé upload. Confirm salary structure, location and selection process with the team.","kind":"faq"},{"topic":"sales opening","aliases":["sales executive"],"answer":"Sales Executive: advertised salary ₹3.5 LPA. Apply through the separate career form with your résumé. Confirm role arrangements and selection details with the team.","kind":"faq"},{"topic":"lead generation opening","aliases":["lead generation executive"],"answer":"Lead Generation Executive: advertised salary ₹4 LPA. Apply through Careers with the separate candidate form and résumé. Confirm salary structure and selection details with the team.","kind":"faq"},{"topic":"job application","aliases":["career application","job application","apply for job","resume upload"],"answer":"Careers has a separate candidate form for contact, education, experience, skills and availability. Upload a PDF, DOC or DOCX résumé up to 5 MB. The question about interest in the role is optional.","kind":"faq"},{"topic":"contact email","aliases":["email","contact","phone","call","enquiry"],"answer":"Email qelvioratechnologies@gmail.com or call +91 70607 11685. Enquiry forms appear on every main page. This chat does not submit an enquiry; use Talk to our team.","kind":"faq"},{"topic":"form delivery","aliases":["form submit","formsubmit","form details","email delivery"],"answer":"Forms are configured for qelvioratechnologies@gmail.com. FormSubmit requires inbox activation before receiving submissions. Open the site through its server launcher or hosting; file:// submissions will not work. Actual delivery is not verified by this chat.","kind":"faq"},{"topic":"upload limits","aliases":["attachment size","file size","upload limit"],"answer":"Career résumés and payment receipts are limited to 5 MB. Career accepts PDF/DOC/DOCX; payment proof accepts PNG/JPG/PDF. Practice forms also accept TXT and the listed document/image formats.","kind":"faq"},{"topic":"login","aliases":["login","sign up","signup","account required"],"answer":"No login is needed to view programs, learn skills, use the career finder or practise quizzes. Quiz results and lesson notes are not saved.","kind":"faq"},{"topic":"live ai status","aliases":["live ai","ai connected","chatbot ai"],"answer":"The chatbot currently uses published-information answers. Live AI requires server configuration and is not confirmed as connected. Confirm important details with the team.","kind":"faq"},{"topic":"company overview","aliases":["qelviora technologies","about company","who are you"],"answer":"Qelviora Technologies provides EdTech and IT solutions. Learn | Build | Grow. The site lists 8 technology services, 11 training programs and 43 skill guides.","kind":"faq"},{"topic":"company delivery","aliases":["projects delivered","client count","international client","national client"],"answer":"Qelviora reports 15 projects delivered and 20+ clients in national and international markets.","kind":"faq"},{"topic":"beginner route","aliases":["beginner","which course","recommend course"],"answer":"Use Find Your Path for a route based on your background and interests. Interface development, complete applications, data analysis and business analysis offer different starting points; review curricula before choosing.","kind":"faq"},{"topic":"portfolio guide","aliases":["portfolio building"],"answer":"Career Center → Portfolio Building helps you select relevant projects, explain decisions and show outcomes. Use public or synthetic data and describe limitations honestly.","kind":"faq"},{"topic":"mock interview","aliases":["mock interview"],"answer":"Career Center → Mock Interviews explains how to prepare your target role, résumé and project examples. Ask the team about availability and format.","kind":"faq"},{"topic":"navigation","aliases":["programs menu","where to find"],"answer":"Programs contains Training Programs, Internships, Projects and Career Center. Learning Experience contains Details and Quiz. Find Your Path is a separate navbar button.","kind":"faq"},{"topic":"Full Stack Development","aliases":["Full Stack Development","fullstack","full stack","full-stack"],"kind":"program","answer":"Full Stack Development is a 6-month program. Build complete web applications. Learning focus: Frontend foundations; Backend APIs and databases; Full-stack projects and deployment. View its program details and apply through the enquiry form. Confirm fees, entry requirements and batch dates with the team."},{"topic":"Frontend Development","aliases":["Frontend Development","front end","frontend"],"kind":"program","answer":"Frontend Development is a 4-month program. Create responsive, accessible interfaces. Learning focus: HTML, CSS and responsive layouts; JavaScript and component-based interfaces; Practical UI projects. View its program details and apply through the enquiry form. Confirm fees, entry requirements and batch dates with the team."},{"topic":"Backend Development","aliases":["Backend Development","back end","backend"],"kind":"program","answer":"Backend Development is a 4-month program. Build the systems behind modern applications. Learning focus: Server-side programming and APIs; Databases, authentication and validation; Backend projects and testing. View its program details and apply through the enquiry form. Confirm fees, entry requirements and batch dates with the team."},{"topic":"Data Analyst","aliases":["Data Analyst","data analyst course","data analytics course"],"kind":"program","answer":"Data Analyst is a 4-month program. Turn data into clear, useful insights. Learning focus: Data cleaning and exploration; SQL, reporting and dashboards; Communicating business insights. View its program details and apply through the enquiry form. Confirm fees, entry requirements and batch dates with the team."},{"topic":"Data Science","aliases":["Data Science"],"kind":"program","answer":"Data Science is a 6-month program. Explore patterns and solve data-driven problems. Learning focus: Python and statistics; Data preparation and analysis; Experiments and evaluation. View its program details and apply through the enquiry form. Confirm fees, entry requirements and batch dates with the team."},{"topic":"Generative AI","aliases":["Generative AI","gen ai","generative ai course"],"kind":"program","answer":"Generative AI is a 6-month program. Build practical workflows with generative AI. Learning focus: Prompting and model capabilities; AI-assisted workflows and applications; Responsible use and evaluation. View its program details and apply through the enquiry form. Confirm fees, entry requirements and batch dates with the team."},{"topic":"Human Resource","aliases":["Human Resource","hr course","human resources"],"kind":"program","answer":"Human Resource is a 3-month program. Build a foundation in people operations. Learning focus: Recruitment and communication; Employee lifecycle and HR processes; Workplace scenarios and documentation. View its program details and apply through the enquiry form. Confirm fees, entry requirements and batch dates with the team."},{"topic":"Business Analyst","aliases":["Business Analyst"],"kind":"program","answer":"Business Analyst is a 4-month program. Connect business needs with actionable requirements. Learning focus: Requirement gathering and analysis; Process mapping and documentation; Stakeholder communication. View its program details and apply through the enquiry form. Confirm fees, entry requirements and batch dates with the team."},{"topic":"Artificial Intelligence","aliases":["Artificial Intelligence","ai course","artificial intelligence"],"kind":"program","answer":"Artificial Intelligence is a 6-month program. Understand and apply intelligent systems. Learning focus: AI foundations and applications; Data-driven problem solving; Practical projects and responsible AI. View its program details and apply through the enquiry form. Confirm fees, entry requirements and batch dates with the team."},{"topic":"Machine Learning","aliases":["Machine Learning","ml course"],"kind":"program","answer":"Machine Learning is a 6-month program. Prepare, train and evaluate predictive models. Learning focus: Supervised and unsupervised learning; Feature preparation and evaluation; Practical model-building projects. View its program details and apply through the enquiry form. Confirm fees, entry requirements and batch dates with the team."},{"topic":"Communication Skills","aliases":["Communication Skills"],"kind":"program","answer":"Communication Skills is a 3-month program. Communicate clearly and confidently in professional settings. Learning focus: Speaking and listening foundations; Workplace communication and presentation; Interview communication and practical exercises. Total ₹7,999: ₹7,000 training + ₹999 registration. Use its separate registration form; payment requires team verification."},{"topic":"Web & App Development Service","aliases":["web development service","app development","web and app","website development"],"kind":"service","answer":"Web & App Development: Responsive websites and applications built around your users and business needs. Submit your requirements through the enquiry form so the team can confirm scope, pricing and delivery arrangements."},{"topic":"AI Automation Service","aliases":["ai automation","workflow automation"],"kind":"service","answer":"AI Automation: Streamline repetitive workflows and put AI to work in practical business processes. Submit your requirements through the enquiry form so the team can confirm scope, pricing and delivery arrangements."},{"topic":"Business Analysis Service","aliases":["business analysis service","business analysis"],"kind":"service","answer":"Business Analysis: Clarify requirements, map processes and identify opportunities for improvement. Submit your requirements through the enquiry form so the team can confirm scope, pricing and delivery arrangements."},{"topic":"Data Analysis Service","aliases":["data analysis service","data analysis"],"kind":"service","answer":"Data Analysis: Organise data, uncover patterns and present useful insights through reports and dashboards. Submit your requirements through the enquiry form so the team can confirm scope, pricing and delivery arrangements."},{"topic":"SEO Service","aliases":["seo","search engine optimisation","search engine optimization"],"kind":"service","answer":"SEO: Improve search visibility through technical, on-page and content optimisation. Submit your requirements through the enquiry form so the team can confirm scope, pricing and delivery arrangements."},{"topic":"Digital Marketing Service","aliases":["digital marketing"],"kind":"service","answer":"Digital Marketing: Plan and execute digital campaigns around your audience, goals and channels. Submit your requirements through the enquiry form so the team can confirm scope, pricing and delivery arrangements."},{"topic":"Lead Generation Service","aliases":["lead generation service","lead generation"],"kind":"service","answer":"Lead Generation: Develop targeted lead journeys and outreach strategies for your business. Submit your requirements through the enquiry form so the team can confirm scope, pricing and delivery arrangements."},{"topic":"Google Business Profile Optimization Service","aliases":["google profile","google business profile","profile optimization"],"kind":"service","answer":"Google Business Profile Optimization: Improve business information, local content and profile presentation for local discovery. Submit your requirements through the enquiry form so the team can confirm scope, pricing and delivery arrangements."},{"topic":"Data Analytics Internship","aliases":["Data Analytics internship"],"kind":"internship","answer":"Data Analytics Internship offers 1, 2, 3 or 6 months at applicant fees of ₹499, ₹999, ₹1,299 or ₹1,999. Benefits include monthly tasks, assessments, notes and project support, plus an internship certificate and experience letter after completion requirements. Use Apply for Paid Internship, upload payment proof and wait for team verification. Confirm availability and terms."},{"topic":"AI/ML Internship","aliases":["AI/ML internship"],"kind":"internship","answer":"AI/ML Internship offers 1, 2, 3 or 6 months at applicant fees of ₹499, ₹999, ₹1,299 or ₹1,999. Benefits include monthly tasks, assessments, notes and project support, plus an internship certificate and experience letter after completion requirements. Use Apply for Paid Internship, upload payment proof and wait for team verification. Confirm availability and terms."},{"topic":"Web Development Internship","aliases":["Web Development internship"],"kind":"internship","answer":"Web Development Internship offers 1, 2, 3 or 6 months at applicant fees of ₹499, ₹999, ₹1,299 or ₹1,999. Benefits include monthly tasks, assessments, notes and project support, plus an internship certificate and experience letter after completion requirements. Use Apply for Paid Internship, upload payment proof and wait for team verification. Confirm availability and terms."},{"topic":"Business Analytics Internship","aliases":["Business Analytics internship"],"kind":"internship","answer":"Business Analytics Internship offers 1, 2, 3 or 6 months at applicant fees of ₹499, ₹999, ₹1,299 or ₹1,999. Benefits include monthly tasks, assessments, notes and project support, plus an internship certificate and experience letter after completion requirements. Use Apply for Paid Internship, upload payment proof and wait for team verification. Confirm availability and terms."},{"topic":"Digital Marketing Internship","aliases":["Digital Marketing internship"],"kind":"internship","answer":"Digital Marketing Internship offers 1, 2, 3 or 6 months at applicant fees of ₹499, ₹999, ₹1,299 or ₹1,999. Benefits include monthly tasks, assessments, notes and project support, plus an internship certificate and experience letter after completion requirements. Use Apply for Paid Internship, upload payment proof and wait for team verification. Confirm availability and terms."},{"topic":"UI/UX Internship","aliases":["UI/UX internship"],"kind":"internship","answer":"UI/UX Internship offers 1, 2, 3 or 6 months at applicant fees of ₹499, ₹999, ₹1,299 or ₹1,999. Benefits include monthly tasks, assessments, notes and project support, plus an internship certificate and experience letter after completion requirements. Use Apply for Paid Internship, upload payment proof and wait for team verification. Confirm availability and terms."},{"topic":"Cybersecurity Internship","aliases":["Cybersecurity internship"],"kind":"internship","answer":"Cybersecurity Internship offers 1, 2, 3 or 6 months at applicant fees of ₹499, ₹999, ₹1,299 or ₹1,999. Benefits include monthly tasks, assessments, notes and project support, plus an internship certificate and experience letter after completion requirements. Use Apply for Paid Internship, upload payment proof and wait for team verification. Confirm availability and terms."},{"topic":"Portfolio Skill","aliases":["Portfolio skill","learn Portfolio","Portfolio guide"],"kind":"skill","answer":"Portfolio: Present your work clearly to employers and collaborators. Its learning path covers Choose one project and define its purpose; Explain your own contribution and decisions; Organise source files and remove sensitive data; Write setup instructions with expected results; Provide a working demonstration where appropriate; Review the portfolio from a first-time visitor’s perspective. Suggested practice: Prepare a project case study with a README, screenshots and runnable instructions. Open Skills to start learning without login."},{"topic":"Claude Code Skill","aliases":["Claude Code skill","learn Claude Code","Claude Code guide"],"kind":"skill","answer":"Claude Code: Use an AI coding assistant with clear context and careful review. Its learning path covers Describe project structure and development constraints; Break a change into reviewable steps; Review the permissions needed for a task; Give focused requests and relevant context; Inspect changes before accepting them; Run checks and document the resulting behaviour. Suggested practice: Use an assistant to make one small project change and document your review. Open Skills to start learning without login."},{"topic":"LinkedIn Skill","aliases":["LinkedIn skill","learn LinkedIn","LinkedIn guide"],"kind":"skill","answer":"LinkedIn: Make your professional profile clear and relevant. Its learning path covers Write a headline describing your direction; Explain skills with concrete examples; Add projects that demonstrate your contribution; Keep experience and education accurate; Write concise, relevant outreach messages; Review your profile for clarity and consistency. Suggested practice: Draft a profile summary and one project description. Open Skills to start learning without login."},{"topic":"Git & GitHub Skill","aliases":["Git & GitHub skill","learn Git & GitHub","Git & GitHub guide"],"kind":"skill","answer":"Git & GitHub: Organise project history and collaborate through reviewable changes. Its learning path covers Inspect modified files before committing; Create focused commits with useful messages; Use branches for separate changes; Review and resolve conflicting edits carefully; Document setup and usage in the repository; Keep credentials and generated clutter out of version control. Suggested practice: Publish a practice project with a branch and a reviewed change. Open Skills to start learning without login."},{"topic":"JavaScript Skill","aliases":["JavaScript skill","learn JavaScript","JavaScript guide"],"kind":"skill","answer":"JavaScript: Build interactive interfaces using clear programming foundations. Its learning path covers Understand values, types and comparisons; Use functions to organise repeated operations; Transform arrays and access object data; Handle events and update the interface; Manage asynchronous requests and failures; Split reusable logic into modules. Suggested practice: Build a searchable catalogue using sample data. Open Skills to start learning without login."},{"topic":"UI/UX Skill","aliases":["UI/UX skill","learn UI/UX","UI/UX guide"],"kind":"skill","answer":"UI/UX: Make product interfaces easier to understand and use. Its learning path covers Identify the visitor’s main task; Arrange content using a clear hierarchy; Choose readable type, spacing and contrast; Design keyboard-friendly controls; Plan loading, empty and error states; Review the interface with representative tasks. Suggested practice: Redesign a confusing enquiry form and explain each improvement. Open Skills to start learning without login."},{"topic":"REST APIs Skill","aliases":["REST APIs skill","learn REST APIs","REST APIs guide"],"kind":"skill","answer":"REST APIs: Design predictable interfaces between applications. Its learning path covers Name resources consistently; Choose methods that match the operation; Validate requests and required fields; Return meaningful status codes and errors; Define pagination for larger collections; Document example requests and responses. Suggested practice: Design an API for courses and enquiries. Open Skills to start learning without login."},{"topic":"SQL Skill","aliases":["SQL skill","learn SQL","SQL guide"],"kind":"skill","answer":"SQL: Store structured information and query it reliably. Its learning path covers Model records with tables and keys; Use constraints to protect data integrity; Filter and order query results; Join related tables when needed; Aggregate values and check totals; Use parameterised inputs and inspect query plans. Suggested practice: Create a practice database with courses and enquiries. Open Skills to start learning without login."},{"topic":"Authentication Skill","aliases":["Authentication skill","learn Authentication","Authentication guide"],"kind":"skill","answer":"Authentication: Understand identity and secure access in application development. Its learning path covers Distinguish identification, authentication and authorisation; Use established password-hashing approaches; Understand sessions and tokens; Review secure cookie and expiry settings; Control access to protected operations; Check logout, expired sessions and rejected requests. Suggested practice: Draw and review an authentication flow for a fictional app. Open Skills to start learning without login."},{"topic":"TypeScript Skill","aliases":["TypeScript skill","learn TypeScript","TypeScript guide"],"kind":"skill","answer":"TypeScript: Use types to express contracts and catch mistakes earlier. Its learning path covers Describe values with suitable types; Model objects and function inputs; Use unions and narrow uncertain values; Type component or API boundaries; Avoid hiding problems with unnecessary any types; Check the project and handle runtime input separately. Suggested practice: Add types to a small JavaScript data-processing feature. Open Skills to start learning without login."},{"topic":"React Skill","aliases":["React skill","learn React","React guide"],"kind":"skill","answer":"React: Compose interactive interfaces from reusable components. Its learning path covers Break the interface into focused components; Pass data using props; Keep changing interface data in state; Render lists with stable keys; Handle forms and user events; Use effects only when synchronising with external systems. Suggested practice: Build a filterable task or course list. Open Skills to start learning without login."},{"topic":"Next.js Skill","aliases":["Next.js skill","learn Next.js","Next.js guide"],"kind":"skill","answer":"Next.js: Organise a web application with routes and server-aware rendering. Its learning path covers Map the application’s pages and routes; Separate server work from client interactions; Fetch and validate application data; Handle loading and errors in the route flow; Keep secrets outside browser code; Prepare and check a working deployment. Suggested practice: Build a small catalogue with a list and a detail route. Open Skills to start learning without login."},{"topic":"Tailwind CSS Skill","aliases":["Tailwind CSS skill","learn Tailwind CSS","Tailwind CSS guide"],"kind":"skill","answer":"Tailwind CSS: Create consistent layouts through reusable styling decisions. Its learning path covers Understand utility-based styling; Apply spacing and typography consistently; Build responsive layout variations; Design visible focus and interaction states; Keep class combinations understandable; Review repeated patterns for consistency. Suggested practice: Style a responsive catalogue with clear cards and forms. Open Skills to start learning without login."},{"topic":"Express Skill","aliases":["Express skill","learn Express","Express guide"],"kind":"skill","answer":"Express: Build server-side routes with predictable request handling. Its learning path covers Organise routes and middleware; Parse and validate request bodies; Separate business logic from transport handling; Connect routes to application data; Handle errors centrally and safely; Document configuration and API usage. Suggested practice: Build an enquiry API using fictional data. Open Skills to start learning without login."},{"topic":"Full-Stack Skill","aliases":["Full-Stack skill","learn Full-Stack","Full-Stack guide"],"kind":"skill","answer":"Full-Stack: Connect a working interface, API and data layer. Its learning path covers Define the smallest useful user workflow; Model the data needed for the workflow; Build an interface with clear states; Create and validate API operations; Connect the interface to application storage; Test and document the complete journey. Suggested practice: Create a fictional course enquiry tracker. Open Skills to start learning without login."},{"topic":"Deployment Skill","aliases":["Deployment skill","learn Deployment","Deployment guide"],"kind":"skill","answer":"Deployment: Prepare an application for use outside development. Its learning path covers Choose a deployment approach for the stack; Separate configuration from source code; Protect secrets and database credentials; Verify build output and production settings; Check pages and key interactions after deployment; Document updates and recovery steps. Suggested practice: Deploy a static portfolio and verify its links on a phone. Open Skills to start learning without login."},{"topic":"Python Skill","aliases":["Python skill","learn Python","Python guide"],"kind":"skill","answer":"Python: Write understandable programs for data and automation tasks. Its learning path covers Use collections and control flow; Organise logic with functions and modules; Read and write structured files; Handle exceptions with useful messages; Call APIs with validation and error handling; Document dependencies and how to run the tool. Suggested practice: Create a command-line tool that summarises a sample dataset. Open Skills to start learning without login."},{"topic":"Machine Learning Skill","aliases":["Machine Learning skill","learn Machine Learning","Machine Learning guide"],"kind":"skill","answer":"Machine Learning: Learn predictive modelling through careful experiments. Its learning path covers Define a prediction task and dataset; Prepare features without leaking future information; Separate training and evaluation data; Compare a simple baseline with a model; Choose metrics relevant to the task; Inspect errors and explain limitations. Suggested practice: Compare baseline and model results on a practice dataset. Open Skills to start learning without login."},{"topic":"Pandas Skill","aliases":["Pandas skill","learn Pandas","Pandas guide"],"kind":"skill","answer":"Pandas: Prepare and summarise tabular datasets. Its learning path covers Inspect column types and sample records; Find missing values and inconsistent formats; Remove duplicates with a stated rule; Join related datasets carefully; Group records and calculate useful summaries; Check the final data and document transformations. Suggested practice: Clean a fictional sales dataset and summarise revenue by category. Open Skills to start learning without login."},{"topic":"Model Evaluation Skill","aliases":["Model Evaluation skill","learn Model Evaluation","Model Evaluation guide"],"kind":"skill","answer":"Model Evaluation: Measure model performance without misleading conclusions. Its learning path covers Choose a baseline for comparison; Use appropriate validation splits; Select metrics for the business question; Inspect confusion matrices where relevant; Check leakage, imbalance and overfitting; Report uncertainty and failure cases. Suggested practice: Write an evaluation report for a practice classifier. Open Skills to start learning without login."},{"topic":"Prompt Engineering Skill","aliases":["Prompt Engineering skill","learn Prompt Engineering","Prompt Engineering guide"],"kind":"skill","answer":"Prompt Engineering: Design clearer tasks and evaluate generated responses. Its learning path covers State the task and desired outcome; Provide relevant context and constraints; Specify a useful response format; Test with representative examples; Inspect failures and revise instructions; Protect sensitive information in the workflow. Suggested practice: Compare prompts for summarising a fictional project brief. Open Skills to start learning without login."},{"topic":"LLM APIs Skill","aliases":["LLM APIs skill","learn LLM APIs","LLM APIs guide"],"kind":"skill","answer":"LLM APIs: Integrate language-model responses into an application. Its learning path covers Keep API credentials on the server; Define and validate the user request; Handle timeouts and upstream failures; Extract the useful response content; Monitor usage and output length; Check generated output before acting on it. Suggested practice: Build an AI-assisted summary feature using non-sensitive sample text. Open Skills to start learning without login."},{"topic":"RAG Skill","aliases":["RAG skill","learn RAG","RAG guide"],"kind":"skill","answer":"RAG: Connect document retrieval with grounded answers. Its learning path covers Prepare documents for search; Choose meaningful text segments; Retrieve content relevant to the question; Generate an answer using source context; Show references supporting the response; Test unsupported questions and weak retrieval. Suggested practice: Design a document-answering demo with visible source references. Open Skills to start learning without login."},{"topic":"AI Agents Skill","aliases":["AI Agents skill","learn AI Agents","AI Agents guide"],"kind":"skill","answer":"AI Agents: Build bounded workflows that can use tools. Its learning path covers Define the goal and permitted actions; Give tools narrow inputs and outputs; Validate tool arguments and results; Require approval for consequential actions; Set stopping rules and recovery behaviour; Compare the agent with a simpler fixed workflow. Suggested practice: Plan an assistant that drafts a task and asks before taking action. Open Skills to start learning without login."},{"topic":"AI Coding Tools Skill","aliases":["AI Coding Tools skill","learn AI Coding Tools","AI Coding Tools guide"],"kind":"skill","answer":"AI Coding Tools: Use code generation while retaining ownership of changes. Its learning path covers Describe the task and project constraints; Limit the scope of the requested change; Inspect generated code and dependencies; Check behaviour with meaningful tests; Keep secrets out of prompts and source; Document decisions you can explain independently. Suggested practice: Review an AI-generated change and record accepted and rejected suggestions. Open Skills to start learning without login."},{"topic":"Solidity Skill","aliases":["Solidity skill","learn Solidity","Solidity guide"],"kind":"skill","answer":"Solidity: Understand smart-contract logic through a small practice project. Its learning path covers Model state and allowed operations; Define access rules and validation; Understand transaction execution and gas; Test expected and rejected operations; Review external calls and failure behaviour; Use a test environment before considering real deployment. Suggested practice: Write a small test-only contract with documented access rules. Open Skills to start learning without login."},{"topic":"Ethereum Skill","aliases":["Ethereum skill","learn Ethereum","Ethereum guide"],"kind":"skill","answer":"Ethereum: Understand how an application interacts with a blockchain. Its learning path covers Distinguish accounts, contracts and networks; Connect an interface to a test wallet; Read contract state without a transaction; Explain what a transaction requests; Show pending, confirmed and failed states; Keep test-only demonstrations separate from real funds. Suggested practice: Build a test-network interface that reads a sample contract. Open Skills to start learning without login."},{"topic":"Flutter Skill","aliases":["Flutter skill","learn Flutter","Flutter guide"],"kind":"skill","answer":"Flutter: Build a mobile interface with clear application structure. Its learning path covers Organise screens using reusable widgets; Manage state for user interactions; Create navigation between screens; Load data with appropriate failure states; Store suitable local application preferences; Check layout and behaviour on a device. Suggested practice: Build a small mobile catalogue with a details screen. Open Skills to start learning without login."},{"topic":"Docker Skill","aliases":["Docker skill","learn Docker","Docker guide"],"kind":"skill","answer":"Docker: Package an application with repeatable runtime configuration. Its learning path covers Describe the application’s runtime needs; Create an image with a clear build process; Keep unnecessary files out of the image; Configure environment variables safely; Connect application and database services; Document how to start and stop the environment. Suggested practice: Containerise a small practice API with setup instructions. Open Skills to start learning without login."},{"topic":"Data Structures Skill","aliases":["Data Structures skill","learn Data Structures","Data Structures guide"],"kind":"skill","answer":"Data Structures: Choose data organisations that fit the problem. Its learning path covers Compare arrays and linked structures; Use maps for key-based lookup; Understand stacks and queues; Explore trees, heaps and graphs; Describe time and space costs; Test empty inputs and boundary cases. Suggested practice: Create a small interview reference with implementations and examples. Open Skills to start learning without login."},{"topic":"Algorithms Skill","aliases":["Algorithms skill","learn Algorithms","Algorithms guide"],"kind":"skill","answer":"Algorithms: Solve common problems with explainable approaches. Its learning path covers Clarify inputs, outputs and constraints; Start with a correct simple solution; Recognise search, sorting and traversal patterns; Use recursion or iteration deliberately; Explain complexity and trade-offs; Test edge cases and document the reasoning. Suggested practice: Solve a selection of practice problems and explain each approach. Open Skills to start learning without login."},{"topic":"OOP Skill","aliases":["OOP skill","learn OOP","OOP guide"],"kind":"skill","answer":"OOP: Model software responsibilities through objects and interfaces. Its learning path covers Define cohesive classes and responsibilities; Encapsulate implementation details; Choose composition or inheritance carefully; Use interfaces for suitable boundaries; Avoid tight coupling between components; Test behaviour through clear public interfaces. Suggested practice: Model a fictional booking workflow using a small set of classes. Open Skills to start learning without login."},{"topic":"Design Patterns Skill","aliases":["Design Patterns skill","learn Design Patterns","Design Patterns guide"],"kind":"skill","answer":"Design Patterns: Use established structures when they solve a real design problem. Its learning path covers Identify the recurring problem first; Compare a simple solution with a pattern; Explore creation and composition approaches; Separate changing behaviour behind interfaces; Refactor without changing required behaviour; Explain the added complexity and benefit. Suggested practice: Refactor a small feature and justify whether a pattern helps. Open Skills to start learning without login."},{"topic":"System Design Skill","aliases":["System Design skill","learn System Design","System Design guide"],"kind":"skill","answer":"System Design: Explain the structure and trade-offs of a practical system. Its learning path covers Clarify expected users and core workflows; Identify components and data boundaries; Choose APIs and storage needs; Consider caching and background work; Plan failures and operational visibility; Explain trade-offs and growth constraints. Suggested practice: Sketch a fictional appointment platform and discuss bottlenecks. Open Skills to start learning without login."},{"topic":"Testing Skill","aliases":["Testing skill","learn Testing","Testing guide"],"kind":"skill","answer":"Testing: Verify important behaviour at useful boundaries. Its learning path covers Choose requirements worth checking; Write focused tests for application logic; Check APIs and validation boundaries; Cover errors and edge cases; Keep tests independent and repeatable; Use automated checks when changes are made. Suggested practice: Create tests for a form and its API. Open Skills to start learning without login."},{"topic":"SQL for Analytics Skill","aliases":["SQL for Analytics skill","learn SQL for Analytics","SQL for Analytics guide"],"kind":"skill","answer":"SQL for Analytics: Answer business questions using structured queries. Its learning path covers Define a clear metric and time window; Filter records using consistent rules; Aggregate and compare relevant groups; Use joins without double-counting; Explore ranking and window calculations; Validate totals and explain limitations. Suggested practice: Analyse fictional product activity using queries and a short report. Open Skills to start learning without login."},{"topic":"Statistics Skill","aliases":["Statistics skill","learn Statistics","Statistics guide"],"kind":"skill","answer":"Statistics: Understand data variation and the limits of evidence. Its learning path covers Compare typical values with mean and median; Describe spread and unusual observations; Understand samples and selection bias; Distinguish association from causation; Represent uncertainty honestly; Match conclusions to the available evidence. Suggested practice: Compare two fictional groups and explain what the data cannot establish. Open Skills to start learning without login."},{"topic":"Data Visualisation Skill","aliases":["Data Visualisation skill","learn Data Visualisation","Data Visualisation guide"],"kind":"skill","answer":"Data Visualisation: Communicate data with clear and honest charts. Its learning path covers Start with the question the chart answers; Choose a suitable visual representation; Label units, axes and categories; Use colour to clarify meaning; Avoid misleading scales or comparisons; Review the chart alongside the underlying values. Suggested practice: Create a small dashboard from a fictional business dataset. Open Skills to start learning without login."},{"topic":"Java Skill","aliases":["Java skill","learn Java","Java guide"],"kind":"skill","answer":"Java: Build a structured command-line application. Its learning path covers Understand values, control flow and types; Organise logic into classes and methods; Use collections for practical tasks; Read data and handle exceptions; Write checks for application behaviour; Document building and running the project. Suggested practice: Build a fictional inventory command-line tool. Open Skills to start learning without login."},{"topic":"C++ Skill","aliases":["C++ skill","learn C++","C++ guide"],"kind":"skill","answer":"C++: Write predictable programs with careful resource handling. Its learning path covers Understand types, control flow and functions; Use standard containers and algorithms; Organise behaviour through classes; Manage resource lifetime deliberately; Inspect compiler warnings and errors; Test boundary cases and document build steps. Suggested practice: Build a small command-line data-processing project. Open Skills to start learning without login."},{"topic":"Go Skill","aliases":["Go skill","learn Go","Go guide"],"kind":"skill","answer":"Go: Build a small service with clear interfaces and error handling. Its learning path covers Use types and functions to express behaviour; Organise a project into packages; Handle errors explicitly; Build HTTP handlers and validate requests; Use concurrency only where needed; Test and document the running service. Suggested practice: Create a small HTTP service with validation and tests. Open Skills to start learning without login."},{"topic":"Rust Skill","aliases":["Rust skill","learn Rust","Rust guide"],"kind":"skill","answer":"Rust: Use ownership and types to write dependable application logic. Its learning path covers Understand ownership and borrowing; Model values using structs and enums; Handle recoverable errors with Result; Work with collections and iterators; Use modules and tests to organise the project; Document how to build and run a small tool. Suggested practice: Build a command-line tool that validates a sample file. Open Skills to start learning without login."},{"topic":"HTML & CSS Skill","aliases":["HTML & CSS skill","learn HTML & CSS","HTML & CSS guide"],"kind":"skill","answer":"HTML & CSS: Build accessible page structure and responsive layouts. Its learning path covers Use semantic landmarks and headings; Create labelled, keyboard-friendly forms; Understand the box model and sizing; Arrange content with Flexbox and Grid; Adapt layouts to smaller screens; Check readability, contrast and focus states. Suggested practice: Build a responsive landing page with a working navigation structure. Open Skills to start learning without login."},{"topic":"Retail Sales Intelligence Dashboard","aliases":["Retail Sales Intelligence Dashboard"],"kind":"project","answer":"Retail Sales Intelligence Dashboard uses SQL, Power BI and Python; suggested practice time 3–4 weeks. The brief asks for a documented repository or workbook, decisions and limitations, and a portfolio case study. Start Practice opens a separate form with the project selected."},{"topic":"Customer Segmentation Analysis","aliases":["Customer Segmentation Analysis"],"kind":"project","answer":"Customer Segmentation Analysis uses Python, Pandas and clustering; suggested practice time 3 weeks. The brief asks for a documented repository or workbook, decisions and limitations, and a portfolio case study. Start Practice opens a separate form with the project selected."},{"topic":"Loan Eligibility Prediction","aliases":["Loan Eligibility Prediction"],"kind":"project","answer":"Loan Eligibility Prediction uses Python, Scikit-learn and statistics; suggested practice time 4 weeks. Use synthetic data and do not make real lending decisions. The brief asks for a documented repository or workbook, decisions and limitations, and a portfolio case study. Start Practice opens a separate form with the project selected."},{"topic":"E-Commerce Analytics","aliases":["E-Commerce Analytics"],"kind":"project","answer":"E-Commerce Analytics uses Excel, SQL and Power BI; suggested practice time 2–3 weeks. The brief asks for a documented repository or workbook, decisions and limitations, and a portfolio case study. Start Practice opens a separate form with the project selected."},{"topic":"AI Resume Screening","aliases":["AI Resume Screening"],"kind":"project","answer":"AI Resume Screening uses Python, NLP and evaluation; suggested practice time 4 weeks. Use synthetic résumés and do not make automated employment decisions. The brief asks for a documented repository or workbook, decisions and limitations, and a portfolio case study. Start Practice opens a separate form with the project selected."}];
function guide(query){const normal=s=>s.toLowerCase().replace(/&/g," and ").replace(/[^a-z0-9]+/g," ").trim();const q=normal(query).replace(/\bfees\b/g,"fee").replace(/\bassessments\b/g,"assessment").replace(/\btasks\b/g,"task");if(!q||/^(hi|hello|hey|good morning|good evening)$/.test(q))return "Hello! Ask about a course, service, internship fee, project, quiz or application form.";
if(/\bquiz\b/.test(q)){const matched=knowledgeEntries.find(e=>(e.kind==="skill"||e.kind==="program")&&e.aliases.some(a=>q.includes(normal(a.replace(/ skill$| guide$/,"")))));return (matched?matched.topic.replace(/ Skill$/,"")+": ":"")+"Learning Experience → Quiz offers 51 skills, 20 quizzes per skill and 3 questions per quiz. Search your skill, select a quiz and check your answers for an immediate score. Scores are not saved."}
const hits=knowledgeEntries.map((e,index)=>{let score=0;for(const alias of e.aliases){const a=normal(alias);if((" "+q+" ").includes(" "+a+" "))score=Math.max(score,a.length)}return {e,score,index}}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score||a.index-b.index);if(hits.length){const e=hits[0].e;if(e.kind==="program"&&/\b(fee|fees|cost|price|pricing)\b/.test(q)&&e.topic!=="Communication Skills")return e.topic+": its course fee is not published. Use its program enquiry form to ask the team for confirmed pricing and payment terms.";return e.answer}
if(/\b(service|services)\b/.test(q))return "Our services: "+services.map(s=>s[0]).join(", ")+". Ask about one service for its specific information.";
if(/\b(program|programs|course|courses|training|duration)\b/.test(q))return programs.map(p=>p[1]+" — "+p[2]+" months").join("\n")+"\nAsk about a named program for its learning focus and application details.";
if(/\b(opening|vacancy|vacancies|salary|jobs)\b/.test(q))return "Careers lists Business Development Executive (Fresher) ₹3.5 LPA, Sales Executive ₹3.5 LPA and Lead Generation Executive ₹4 LPA. Each uses the separate candidate application form.";
return "Try asking a specific question, such as ‘Frontend Development’, ‘AI automation’, ‘internship fees’, ‘monthly assessments’, ‘quiz library’ or ‘payment proof’. For individual guidance, use Talk to our team.";}
async function ask(text){if(busy)return;busy=true;const current=generation;bubble(text,"user");history.push({role:"user",content:text});input.value="";const send=form.querySelector("button");send.disabled=true;const pending=bubble(aiAvailable?"Thinking…":"Checking program information…","assistant");try{let answer;if(aiAvailable){const response=await fetch("/api/assistant",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({messages:history.slice(-10)}),signal:AbortSignal.timeout(25000)});const data=await response.json();if(!response.ok||!data.reply)throw Error("AI unavailable");answer=data.reply}else answer=guide(text);if(current!==generation)return;pending.textContent=answer;history.push({role:"assistant",content:answer});messages.scrollTop=messages.scrollHeight}catch{if(current===generation)pending.textContent="Live AI is temporarily unavailable. Here is the program guide answer:\n\n"+guide(text)}finally{busy=false;send.disabled=false;if(!panel.hidden)input.focus()}}
form.addEventListener("submit",e=>{e.preventDefault();const text=input.value.trim();if(text)ask(text)});
document.querySelectorAll("[data-prompt]").forEach(b=>b.addEventListener("click",()=>ask(b.dataset.prompt)));welcome();
if(location.protocol==="http:"||location.protocol==="https:")fetch("/api/assistant/status",{signal:AbortSignal.timeout(5000)}).then(r=>r.ok?r.json():null).then(data=>{if(data?.available){aiAvailable=true;mode.textContent="AI assistant";notice.textContent="AI replies can make mistakes. Confirm fees and schedules with our team. Messages are sent to the AI provider; avoid sharing sensitive details."}}).catch(()=>{});
})();
